// Append renders the SVG presentation while reusing buffers retained by w.
func (w *ArasySplashWorkspace) Append(timeline anim.Timeline, viewport math2d.Rect, resources ArasySplashResources) []render.Command {
	if w == nil {
		return AppendArasySplash(nil, timeline, viewport, resources)
	}
	if cap(w.commands) < ArasySplashAssetMetrics.CommandCapacity {
		w.commands = make([]render.Command, 0, ArasySplashAssetMetrics.CommandCapacity)
	}
	scale := arasySplashScale(viewport)
	w.lod = svgLODWithHysteresis(w.lod, w.lodReady, scale)
	w.lodReady = true
	w.frameMetrics = ArasySplashFrameMetrics{LOD: w.lod, Tolerance: svgLODTolerance(w.lod)}
	w.commands = appendArasySplash(
		w.commands[:0], timeline, viewport, resources, &w.builder,
		w.fills[:], w.strokes[:], w.frameMetrics.Tolerance, &w.frameMetrics,
	)
	return w.commands
}

// FrameMetrics returns traversal and LOD data from the latest Append call.
func (w *ArasySplashWorkspace) FrameMetrics() ArasySplashFrameMetrics {
	if w == nil {
		return ArasySplashFrameMetrics{}
	}
	return w.frameMetrics
}

// AppendArasySplash appends the SVG presentation at timeline time into dst.
func AppendArasySplash(dst []render.Command, timeline anim.Timeline, viewport math2d.Rect, resources ArasySplashResources) []render.Command {
	scale := arasySplashScale(viewport)
	return appendArasySplash(
		dst, timeline, viewport, resources, nil, nil, nil,
		svgLODTolerance(svgLOD(scale)), nil,
	)
}

func arasySplashScale(viewport math2d.Rect) float64 {
	return math.Min(viewport.Width()/1920, viewport.Height()/1080)
}

func appendArasySplash(
	dst []render.Command,
	timeline anim.Timeline,
	viewport math2d.Rect,
	resources ArasySplashResources,
	builder *render.Builder,
	fillWorkspaces []vector.FillWorkspace,
	strokeWorkspaces []vector.StrokeWorkspace,
	tolerance float64,
	frameMetrics *ArasySplashFrameMetrics,
) []render.Command {
	if builder == nil {
		builder = &render.Builder{}
	}
	builder.Reset(dst)
	scale := arasySplashScale(viewport)
	offset := math2d.Vec2{
		X: viewport.Min.X + (viewport.Width()-1920*scale)*0.5 - 0*scale,
		Y: viewport.Min.Y + (viewport.Height()-1080*scale)*0.5 - 0*scale,
	}
	builder.Push(render.Group{Transform: math2d.Translate(offset).Mul(math2d.Scale(math2d.Vec2{X: scale, Y: scale})), Opacity: 1})
	// Bounds checks pay for themselves on larger node sets. Small assets skip
	// the per-node matrix/bounds work and retain the straight traversal.
	appendSVGNode(
		builder, arasySplashNodes, 0, timeline, resources.font,
		fillWorkspaces, strokeWorkspaces, tolerance,
		math2d.Rect{Min: math2d.Vec2{X: 0, Y: 0}, Max: math2d.Vec2{X: 1920, Y: 1080}}, ArasySplashAssetMetrics.Nodes >= 32, math2d.Identity(), frameMetrics,
	)
	builder.Pop()
	return builder.Commands()
}

func (r ArasySplashResources) font(field uint16) render.FontID {
	switch field {
	default:
		return 0
	}
}
